--
-- Struktur dari tabel `economic_indicators`
--

CREATE TABLE `economic_indicators` (
  `id` bigint UNSIGNED NOT NULL,
  `country_id` bigint UNSIGNED NOT NULL,
  `year` smallint UNSIGNED NOT NULL,
  `gdp` decimal(20,2) DEFAULT NULL,
  `inflation_rate` decimal(6,2) DEFAULT NULL,
  `population` bigint UNSIGNED DEFAULT NULL,
  `export_value` decimal(20,2) DEFAULT NULL,
  `import_value` decimal(20,2) DEFAULT NULL,
  `source` varchar(100) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'World Bank API',
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

