  `source_url` varchar(500) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `category` enum('logistics','trade','shipping','economy','geopolitics') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'economy',
  `sentiment_label` enum('positive','neutral','negative') COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `positive_score` int UNSIGNED NOT NULL DEFAULT '0',
  `negative_score` int UNSIGNED NOT NULL DEFAULT '0',
  `published_at` timestamp NULL DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

--
-- Dumping data untuk tabel `news_articles`
