INSERT INTO `news_articles` (`id`, `country_id`, `title`, `summary`, `source_name`, `source_url`, `category`, `sentiment_label`, `positive_score`, `negative_score`, `published_at`, `created_at`) VALUES
(1, NULL, 'Accenture chosen by DOD to investigate medicine supply chain, DefenseScoop says', 'The Assistant Secretary of Defense for Health Affairs, in partnership with the Defense Health Agency and Defense Logistics Agency, selected Acce...', 'Markets Insider', 'https://markets.businessinsider.com/news/stocks/accenture-chosen-by-dod-to-investigate-medicine-supply-chain-defensescoop-says-1036338255', 'logistics', 'positive', 1, 0, '2026-07-17 11:50:18', '2026-07-19 06:06:06'),
(2, NULL, 'Leidos and DHL form alliance to strengthen the future of UK Defence logistics', '/PRNewswire/ -- Leidos (NYSE: LDOS) and DHL Supply Chain have formed a strategic alliance to bring integrated, resilient and scalable logistics capabilities...', 'PR Newswire UK', 'https://www.prnewswire.co.uk/news-releases/leidos-and-dhl-form-alliance-to-strengthen-the-future-of-uk-defence-logistics-302828093.html', 'logistics', 'positive', 2, 0, '2026-07-17 02:45:00', '2026-07-19 06:06:06'),
(3, 109, 'Logistics firms set for strong Q1 revenue growth despite margin pressure', 'Logistics sector revenue is poised for healthy growth in the June quarter. This expansion is driven by e-commerce demand and increased supply-chain outsourcing. However, elevated fuel costs and pricing pressures may impact profitability across companies. Container Corporation of India and Delhivery anticipate revenue increases with margin challenges. Blue Dart Express and TCI also expect revenue growth, with fuel prices being key.', 'The Economic Times', 'https://economictimes.indiatimes.com/markets/stocks/earnings/logistics-firms-set-for-strong-q1-revenue-growth-despite-margin-pressure/articleshow/132450304.cms', 'logistics', 'positive', 4, 0, '2026-07-16 17:50:00', '2026-07-19 06:06:06'),
(4, NULL, 'Wabash Announces Pricing of Upsized Offering of $130 Million Convertible Senior Notes', 'LAFAYETTE, Ind., July 16, 2026 (GLOBE NEWSWIRE) -- Wabash (NYSE: WNC), a leader in end-to-end supply chain solutions for the transportation, logistics and infrastructure markets, announced today the pricing of its upsized private offering (the \'Offering”) of $130 million aggregate principal amount of 4.00% convertible senior unsecured notes due 2032 (the \'notes”), which was upsized from the previously announced $100 million aggregate principal amount of notes, to persons reasonably believed to be qualified institutional buyers pursuant to Rule 144A under the Securities Act of 1933, as amended (the \'Securities Act”). In addition, Wabash granted the initial purchasers of the notes an option to purchase, for settlement within a 13-day period beginning on, and including, the date on which the notes are first issued, up to an additional $20 million aggregate principal amount of the notes. The Offering is expected to close on July 20, 2026, subject to customary closing conditions.', 'The Manila Times', 'https://www.manilatimes.net/2026/07/16/tmt-newswire/globenewswire/wabash-announces-pricing-of-upsized-offering-of-130-million-convertible-senior-notes/2385734', 'logistics', 'neutral', 0, 0, '2026-07-16 03:33:36', '2026-07-19 06:06:06'),
(5, NULL, 'Philippine real estate sector still resilient mid-year despite ongoing headwinds - Lobien', 'Halfway through 2026, the Philippine real estate sector is still proving to be resilient despite the economic shocks brought by the Middle East crisis, as well as uncertainties brought about by the recent tumultuous movements in the Senate. The IT-BPM industry has increased its office market share in Metro Manila from 45 percent to 52 percent in the first quarter. The resilience of the residential property sector can be seen in the rise of its prices, with the total country price index growing 4.5 percent year-on-year (YOY). Finally, the continuous expansion of warehouse and logistics investments beyond the National Capital Region (NCR) is fueled by factors like infrastructure projects, e-commerce growth, and supply chain modernization.', 'The Manila Times', 'https://www.manilatimes.net/2026/07/15/business/real-estate-and-property/philippine-real-estate-sector-still-resilient-mid-year-despite-ongoing-headwinds-lobien/2384780', 'logistics', 'positive', 4, 1, '2026-07-15 00:24:00', '2026-07-19 06:06:06'),
(6, NULL, 'Defense industry gathers in Pennsylvania as US weapon stockpiles hit new low', 'Keystone State companies produce thousands of parts along the US military\'s supply chain, playing vital roles in producing ships, vehicles and weapons, a new logistics report has found.', 'New York Post', 'https://nypost.com/2026/07/14/us-news/defense-industry-gathers-in-pennsylvania-as-us-weapon-stockpiles-hit-new-low/', 'logistics', 'neutral', 0, 0, '2026-07-14 03:46:28', '2026-07-19 06:06:06'),
(7, NULL, 'Amazon’s Next Business Is Hiding Inside Its Delivery Network (NASDAQ:AMZN)', 'Amazon launches Supply Chain Services to offer cheaper parcel delivery and boost logistics efficiency. Click here to read my most recent analysis of AMZN.', 'Seeking Alpha', 'https://seekingalpha.com/article/4921665-amazons-next-business-is-hiding-inside-its-delivery-network', 'logistics', 'positive', 1, 0, '2026-07-13 12:22:51', '2026-07-19 06:06:06'),
(8, 107, 'KLN Signs MOU with Advantech and YDCare to Support Digital Transformation of Hong Kong\'s Healthcare System', 'HONG KONG, July 13, 2026 /PRNewswire/ -- KLN Logistics Group Limited (\'KLN\'; Stock Code 0636.HK) announced that its healthcare subsidiary, KLN Medical Limited (\'KLN Medical\'), has signed a tripartite Memorandum of Understanding (MOU) with Advantech Co., Ltd. (\'Advantech\'; Stock Code 2395.TW), a global leader in IoT intelligent systems and embedded platforms, and YDCare, a medical nursing brand under New Frontier Group. Under the MOU, KLN Medical will be the sole distributor of Advantech\'s iWard smart ward solutions (\'iWard\') for the Hong Kong market. The partnership aims to synergise the three parties\' expertise across smart healthcare technology, clinical application and medical supply chain management to support the digital transformation of Hong Kong\'s healthcare system and promote the application and development of advanced healthtech.', 'The Manila Times', 'https://www.manilatimes.net/2026/07/13/tmt-newswire/pr-newswire/kln-signs-mou-with-advantech-and-ydcare-to-support-digital-transformation-of-hong-kongs-healthcare-system/2383048', 'logistics', 'positive', 1, 0, '2026-07-12 21:36:15', '2026-07-19 06:06:06'),
(9, 140, 'A.P. Moller acquires stake in AC Logistics', 'DANISH infrastructure fund manager A.P. Moller Capital has completed its acquisition of a 40-percent stake in Ayala Corp.’s AC Logistics Holdings Corp., formalizing a partnership aimed at expanding the logistics company’s operations and supporting supply chain development in the Philippines.', 'The Manila Times', 'https://www.manilatimes.net/2026/07/09/business/corporate-news/ap-moller-acquires-stake-in-ac-logistics/2380992', 'logistics', 'positive', 1, 0, '2026-07-08 09:09:00', '2026-07-19 06:06:06'),
(10, NULL, 'Punjab signs MoU with NICDC logistics arm to digitise state\'s logistics ecosystem', 'Punjab is set to digitally integrate its logistics ecosystem through the Unified Logistics Interface Platform (ULIP), expected to improve supply chain efficiency, support exporters and make logistics operations easier for businesses across the state.', 'The Tribune', 'https://www.tribuneindia.com/news/business/punjab-signs-mou-with-nicdc-logistics-arm-to-digitise-states-logistics-ecosystem/', 'logistics', 'positive', 1, 0, '2026-07-08 06:03:27', '2026-07-19 06:06:06'),
(11, NULL, 'Andhra\'s Bhogapuram airport to be inaugurated on August 1', 'Prime Minister Narendra Modi will inaugurate Andhra Pradesh\'s fourth international airport at Bhogapuram on August 1. Built by GMR Group at a cost of Rs 4,750 crore, the greenfield airport is expected to enhance connectivity, ease pressure on Visakhapatnam Airport, and boost tourism, trade, investment and employment across North Andhra.', 'The Economic Times', 'https://economictimes.indiatimes.com/industry/transportation/airlines-/-aviation/andhras-bhogapuram-airport-to-be-inaugurated-on-august-1/articleshow/132484906.cms', 'trade', 'positive', 2, 0, '2026-07-18 10:46:00', '2026-07-19 06:06:07'),
(12, 172, 'EU assessment report resembles chargesheet on Pakistan’s human rights abuses', 'EU assessment report resembles chargesheet on Pakistan’s human rights abuses - Tel Aviv, July 18 The European Union’s (EU) latest assessment of Pakistan on trade preferences under the Generalised ... Get Latest News on International only on lokmattimes.com', 'Lokmat Times', 'https://www.lokmattimes.com/international/eu-assessment-report-resembles-chargesheet-on-pakistans-human-rights-abuses/', 'trade', 'neutral', 0, 0, '2026-07-18 08:48:08', '2026-07-19 06:06:07'),
(13, 109, 'Kerala: Vizhinjam International Seaport To Begin Full EXIM Operations From August 18, Boosting State\'s Maritime Trade Hub', 'Vizhinjam International Seaport will begin full export-import (EXIM) operations from August 18, expanding beyond transshipment services into a full cargo gateway. The Kerala government will also launch Mission Samudra to strengthen maritime-led economic growth, improve logistics efficiency, boost exports, attract investment and enhance India', 'Free Press Journal', 'https://www.freepressjournal.in/india/kerala-vizhinjam-international-seaport-to-begin-full-exim-operations-from-august-18-boosting-states-maritime-trade-hub', 'trade', 'positive', 5, 0, '2026-07-18 04:30:01', '2026-07-19 06:06:07'),
(14, 82, 'India, Finland eye doubling bilateral trade by 2030 via EU FTA', 'India, Finland eye doubling bilateral trade by 2030 via EU FTA - New Delhi, July 18 India and Finland agreed to deepen economic ties and explore how a proposed EU‑India ... Get Latest News on International only on lokmattimes.com', 'Lokmat Times', 'https://www.lokmattimes.com/international/india-finland-eye-doubling-bilateral-trade-by-2030-via-eu-fta-1/', 'trade', 'neutral', 0, 0, '2026-07-18 03:18:58', '2026-07-19 06:06:07'),
(15, 109, 'Vizhinjam port to begin full EXIM operations from August 18', 'Vizhinjam International Seaport will begin full export-import (EXIM) operations on August 18, transforming from a transshipment hub into a full-fledged cargo gateway. Developed by Kerala government and Adani Ports, the port will launch EXIM services alongside Mission Samudra, boosting logistics, exports, investment, employment and India\'s maritime trade capabilities.', 'The Economic Times', 'https://economictimes.indiatimes.com/industry/transportation/shipping-/-transport/vizhinjam-port-to-begin-full-exim-operations-from-august-18/articleshow/132476259.cms', 'trade', 'positive', 1, 0, '2026-07-18 01:53:00', '2026-07-19 06:06:07'),
(16, 109, 'Chabahar\'s Shahid Beheshti terminal unharmed: India after US bombs port', 'Chabahar, which is being developed by India and Iran to boost connectivity and trade, is also central to efforts by both countries to make it part of the International North-South Transport Corridor.', 'India Today', 'https://www.indiatoday.in/india/story/chabahar-port-us-strikes-india-says-shahid-beheshti-terminal-suffered-no-damage-ptag-2950350-2026-07-17', 'trade', 'positive', 1, 0, '2026-07-17 11:10:00', '2026-07-19 06:06:07'),
(17, NULL, 'Trump official Peter Navarro urges election overhaul', 'Trump official Peter Navarro urges election overhaul - Washington, July 17 Senior White House trade adviser Peter Navarro on Friday defended President Donald Trump\'s renewed focus ... Get Latest News on International only on lokmattimes.com', 'Lokmat Times', 'https://www.lokmattimes.com/international/trump-official-peter-navarro-urges-election-overhaul/', 'trade', 'neutral', 0, 0, '2026-07-17 10:22:43', '2026-07-19 06:06:07'),
(18, NULL, 'Top Russian diplomat says potential closure of Bab el-Mandeb Strait will harm global oil market', 'Russian Foreign Minister Sergey Lavrov on Friday said that the potential closure of the Bab el-Mandeb Strait would harm international trade, particularly the global oil market, Anadolu reports. Res…', 'Middle East Monitor', 'https://www.middleeastmonitor.com/20260717-top-russian-diplomat-says-potential-closure-of-bab-el-mandeb-strait-will-harm-global-oil-market/', 'trade', 'neutral', 0, 0, '2026-07-17 10:20:00', '2026-07-19 06:06:07'),
(19, 2, 'Revival of Hong Kong\'s Special Trade Status Marks Positive Shift in US-China Relations', 'The United States plans to restore Hong Kong\'s special trading status, rescinded in 2020 by President Trump due to China\'s national security law. The decision follows recent trade talks between the US and China, potentially easing trade restrictions and marking a reversal in international relations.', 'Devdiscourse', 'https://www.devdiscourse.com/article/business/3952011-revival-of-hong-kongs-special-trade-status-marks-positive-shift-in-us-china-relations', 'trade', 'neutral', 0, 0, '2026-07-17 07:33:04', '2026-07-19 06:06:07'),
(20, NULL, 'THAIFEX - HOREC ASIA 2027 opens for exhibitor bookings', 'The Department of International Trade Promotion (DITP), Ministry of Commerce, in collaboration with the Thai Chamber of Commerce (TCC) and Koelnmesse (KM), invites entrepreneurs in the hotel, restaurant, café and catering sectors (HoReCa) to participate in THAIFEX – HOREC ASIA 2027 as a platform to expand business opportunities, build partnerships and connect with quality buyers from around the world.', 'Bangkok Post', 'https://www.bangkokpost.com/thailand/pr/3287449/thaifex-horec-asia-2027-opens-for-exhibitor-bookings', 'trade', 'neutral', 0, 0, '2026-07-17 04:20:00', '2026-07-19 06:06:07'),
(21, 2, 'The bridge that linked Iran to Russia and China: Why the US chose to bomb it | Explained', 'The US targeted a strategic bridge on Iran\'s northern trade route, severing a vital rail link to Russia and China. The strike highlights the widening scope of the conflict and its geopolitical implications.', 'Moneycontrol', 'https://www.moneycontrol.com/world/the-bridge-that-linked-iran-to-russia-and-china-why-the-us-chose-to-bomb-it-explained-article-13971215.html', 'geopolitics', 'negative', 0, 2, '2026-07-10 08:52:01', '2026-07-19 06:06:10'),
(22, NULL, 'IMF Adjusts Global Growth Forecast Amid Geopolitical Tensions', 'The International Monetary Fund (IMF) revised its global growth forecast for 2026 to 3.0%, citing risks from the Middle East conflict, trade fragmentation, and AI market corrections. It anticipates a recovery to 3.4% in 2027. The inflation forecast is set at 4.7% for 2026 due to rising energy prices.', 'Devdiscourse', 'https://www.devdiscourse.com/article/business/3947359-imf-adjusts-global-growth-forecast-amid-geopolitical-tensions', 'geopolitics', 'positive', 3, 2, '2026-07-08 09:29:08', '2026-07-19 06:06:10'),
(23, NULL, 'Middle East Conflict Clouds LNG Outlook as Global Trade Hits Record High', 'The International Gas Union says geopolitical turmoil in the Middle East has complicated LNG market forecasts, but record global trade and expanding supply have reinforced LNG\'s role in global energy security.', 'OilPrice', 'https://oilprice.com/Latest-Energy-News/World-News/Middle-East-Conflict-Clouds-LNG-Outlook-as-Global-Trade-Hits-Record-High.html', 'geopolitics', 'negative', 0, 1, '2026-07-07 04:30:00', '2026-07-19 06:06:10'),
(24, 2, 'Why Donald Trump Is Courting India and China at the Same Time', 'Explore how the US is pivoting from Gulf conflict to Asia’s economic giants, rebuilding a fragile trade framework with China while courting India as a strategic partner. This in-depth analysis unpacks the Trump–Xi summit, US–India trade talks, shifting military power after the US–Iran war, and the complex geopolitical shadow cast by Pakistan and Taiwan.', 'Outlook India', 'https://www.outlookindia.com/international/why-donald-trump-is-courting-india-and-china-at-the-same-time', 'geopolitics', 'negative', 0, 2, '2026-06-26 05:23:50', '2026-07-19 06:06:10'),
(25, 115, 'Navigating the Strait of Hormuz: Rising Tensions and Crude Oil Trade', 'Crude oil shipments through the Strait of Hormuz have surged to their highest levels since February\'s U.S.-Israeli conflict with Iran. Despite strong demand, especially in Asia, total sailings remain lower than pre-conflict norms due to geopolitical uncertainties and disrupted AIS tracking signals complicating trade assessments.', 'Devdiscourse', 'https://www.devdiscourse.com/article/science-environment/3940988-navigating-the-strait-of-hormuz-rising-tensions-and-crude-oil-trade', 'geopolitics', 'negative', 0, 2, '2026-06-25 12:12:43', '2026-07-19 06:06:10'),
(26, 115, 'Oil Trade Surges While Navigating Geopolitical Risks in Strait of Hormuz', 'Crude shipments through the Strait of Hormuz have increased after a ceasefire reopened the waterway amid ongoing U.S.-Israeli conflict with Iran. Despite heightened trade, tanker traffic remains below historical norms due to geopolitical uncertainties. The U.N. has implemented an evacuation scheme for vessels trapped due to the conflict.', 'Devdiscourse', 'https://www.devdiscourse.com/article/science-environment/3940917-oil-trade-surges-while-navigating-geopolitical-risks-in-strait-of-hormuz', 'geopolitics', 'negative', 0, 2, '2026-06-25 09:39:10', '2026-07-19 06:06:10'),
(27, NULL, 'Iran war puts Hormuz, Suez trade at risk', 'Iran war puts Hormuz, Suez trade at risk - Washington, July 20 The Trump administration said that oil traffic through the Strait of Hormuz had recovered to ... Get Latest News on International only on lokmattimes.com', 'Lokmat Times', 'https://www.lokmattimes.com/international/iran-war-puts-hormuz-suez-trade-at-risk/', 'trade', 'negative', 0, 2, '2026-07-19 18:10:33', '2026-07-20 10:44:18'),
(28, 2, 'World Uyghur Congress slams Netherlands for ignoring China\'s forced labour, genocide', 'The World Uyghur Congress (WUC) condemned the Dutch government for failing to raise Uyghur forced labour and alleged genocide during its recent China trade mission. Highlighting systematic Chinese repression at UN and international forums, WUC demanded strict enforcement of EU laws to block forced-labour goods from global markets.', 'The Tribune', 'https://www.tribuneindia.com/news/world/world-uyghur-congress-slams-netherlands-for-ignoring-chinas-forced-labour-genocide/', 'trade', 'neutral', 0, 0, '2026-07-19 00:28:01', '2026-07-20 10:44:18'),
(29, NULL, 'Highlights from Adam Silver’s state of the union in Las Vegas', 'NBA commissioner talks domestic and international expansion, the halted Kawhi trade and the current state of the CBA', 'Salt Lake City Deseret News', 'https://www.deseret.com/sports/2026/07/18/highlights-from-adam-silver-state-of-league-in-las-vegas/', 'trade', 'positive', 1, 0, '2026-07-18 16:00:23', '2026-07-20 10:44:18'),
(30, 109, '6.8% GDP Expansion in FY27, Growth to Strengthen in Second Half – Outlook Business', 'Deloitte India has projected the country\'s economy to grow between 6.5 per cent and 6.8 per cent in FY27, with momentum expected to improve in the second half of the fiscal on the back of festive demand, monetary easing and stabilising global conditions. The report highlighted geopolitical tensions, volatile commodity prices, capital outflows and a weaker rupee as near-term challenges. It also flagged inflation, driven by food, fuel and imported commodities, as a key downside risk.', 'Outlook Business', 'https://www.outlookbusiness.com/corporate/deloitte-projects-65-68-gdp-expansion-in-fy27-growth-to-strengthen-in-second-half', 'economy', 'positive', 4, 1, '2026-07-19 02:35:05', '2026-07-20 10:44:21'),
(31, 2, 'Charting the Global Economy: US CPI cools, China growth slows', 'US inflation data eased in June, prompting investors to lower interest rate hike bets. China\'s economy slowed more than anticipated, increasing pressure for government spending while UK consumer-facing services grew in May, driven by retail sales and recreation sectors.', 'The Economic Times', 'https://economictimes.indiatimes.com/small-biz/trade/exports/insights/charting-the-global-economy-us-cpi-cools-china-growth-slows/articleshow/132490075.cms', 'economy', 'neutral', 1, 1, '2026-07-18 22:11:00', '2026-07-20 10:44:21'),
(32, 109, 'Macros strong, but weak rains, war can hit growth: RBI Guv Sanjay Malhotra', 'The Indian economy expanded 7.7% in the last financial year, and the RBI has projected GDP growth of 6.6% for the current fiscal year despite global uncertainties, Sanjay Malhotra said. The governor also flagged inflation risks, noting that the RBI had raised its inflation forecast for FY27 to 5.1% from 4.6% earlier.', 'The Economic Times', 'https://economictimes.indiatimes.com/news/economy/indicators/macros-strong-but-weak-rains-war-can-hit-growth-rbi-guv-sanjay-malhotra/articleshow/132469379.cms', 'economy', 'negative', 2, 3, '2026-07-17 12:32:00', '2026-07-20 10:44:21'),
(33, 138, 'Domestic growth powers on', 'NILAI: Malaysia\'s economy remained resilient in the second quarter despite global uncertainties, with preliminary data showing stronger economic growth and easing inflation, prompting Prime Minister Datuk Seri Anwar Ibrahim to welcome the latest figures.', 'The Star', 'https://www.thestar.com.my/news/nation/2026/07/18/domestic-growth-powers-on', 'economy', 'positive', 3, 1, '2026-07-17 09:00:00', '2026-07-20 10:44:21'),
(34, 109, 'Global economy tipping towards a sharp slowdown, India ‘may lose a step’ too: Moody\'s Analytics', 'The global economy is headed for a slower growth phase over the next two years, with India also expected to lose momentum, as an extended US-Iran conflict threatens to trigger a fresh energy shock, reignite inflation and force central banks into tighter monetary policy, says Moody’s Analytics.', 'Livemint', 'https://www.livemint.com/news/moodys-analytics-global-slowdown-india-ai-boom-11784192376799.html', 'economy', 'negative', 1, 3, '2026-07-16 03:52:33', '2026-07-20 10:44:21'),
(35, 109, 'Global growth set to slow to 2.5% and India \'will lose a step too\': Moody\'s Analytics', 'Moody\'s Analytics expects global growth to slow to 2.5% in 2026, saying India too \"will lose a step\" amid a broader moderation in activity. The report said the AI boom has prevented a steeper downturn but warned that geopolitical tensions, trade frictions and inflation continue to pose downside risks to the global economy.', 'The Economic Times', 'https://economictimes.indiatimes.com/news/economy/indicators/global-growth-set-to-slow-to-2-5-and-india-will-lose-a-step-too-moodys-analytics/articleshow/132431494.cms', 'economy', 'neutral', 2, 2, '2026-07-15 23:50:00', '2026-07-20 10:44:21'),
(36, 2, 'China\'s Economy Grows 4.3% in Q2, Slowest Since 2022', 'China has largely shrugged off wider economic impacts from the Iran war as soaring energy prices pushed up global inflation', 'Deccan Chronicle', 'https://www.deccanchronicle.com/world/neighbours/chinas-economy-grows-43-in-q2-slowest-since-2022-1971291', 'economy', 'negative', 0, 2, '2026-07-15 20:01:41', '2026-07-20 10:44:21'),
(37, NULL, 'Global Market: ECB monitoring Middle East conflict for inflation risks', 'The European Central Bank sees no immediate inflation fallout from the Iran conflict. Policymakers are closely watching for indirect price pressures and their potential impact. The eurozone economy has shown resilience despite ongoing geopolitical tensions and uncertainty. Medium and long-term inflation expectations remain well anchored, reflecting confidence. The bank stands ready to adjust policy if inflation risks increase significantly.', 'The Economic Times', 'https://economictimes.indiatimes.com/markets/us-stocks/news/global-market-ecb-monitoring-middle-east-conflict-for-inflation-risks/articleshow/132409932.cms', 'economy', 'negative', 2, 7, '2026-07-15 00:46:00', '2026-07-20 10:44:21'),
(38, 109, 'Trump\'s Strait of Hormuz Plan Explained: Can the US charge ships and what it means for India', 'Strait of Hormuz Explained: US President Donald Trump\'s proposal to impose a 20% charge on cargo passing through the Strait of Hormuz has sparked a sharp rebuttal from Iran and raised fresh concerns over oil prices, global trade and India\'s economy. Here\'s what international law says, why the UN opposes transit tolls, and how the plan could affect India\'s inflation, crude oil imports, LNG supplies, rupee and fiscal outlook.', 'The Economic Times', 'https://economictimes.indiatimes.com/industry/energy/oil-gas/can-trump-take-control-of-strait-of-hormuz-charge-ships-toll-impact-on-india-trumps-strait-of-hormuz-plan-explained/articleshow/132386769.cms', 'economy', 'negative', 0, 1, '2026-07-14 02:16:00', '2026-07-20 10:44:21'),
(39, NULL, 'Iran war continues to cloud global economy\'s outlook', 'IMF underscored the lingering risks for growth and inflation from the conflict in West Asia, and Bloomberg Economics warned elevated interest rates are here to stay.', 'Moneycontrol', 'https://www.moneycontrol.com/world/iran-war-continues-to-cloud-global-economy-s-outlook-article-13971654.html', 'economy', 'negative', 1, 3, '2026-07-11 08:00:45', '2026-07-20 10:44:21'),
