(41, NULL, 'Mahindra Logistics returns to profit in Q1FY26, revenue rises 23%', 'Mahindra Logistics Limited reported a return to profitability in Q1FY26 with a consolidated net profit of ₹25.39 crore, compared to a net loss of ₹10.80 crore in the same period last year. Revenue from operations increased 23% year-on-year to ₹2,002.88 crore, driven by growth in Supply Chain Management and Enterprise Mobility Services. EBITDA improved to ₹115.09 crore, with margins expanding to 5.76%.', 'scanx.trade', 'https://scanx.trade/stock-market-news/companies/mahindra-logistics-swings-to-profit-in-q1-revenue-jumps-to-20b-rupees-yoy/46080020', 'logistics', 'positive', 3, 0, '2026-07-20 01:03:17', '2026-07-21 03:45:13'),
(42, NULL, 'A Promising Dialogue Across the Atlantic', 'U.S. President Donald Trump announced a fruitful conversation with the UK’s new Prime Minister, Andy Burnham, discussing substantive topics such as North Sea Oil, trade agreements, military partnerships, and other global affairs. A meeting is anticipated shortly, signaling potential cooperation on key international issues.', 'Devdiscourse', 'https://www.devdiscourse.com/article/politics/3953165-a-promising-dialogue-across-the-atlantic', 'trade', 'positive', 1, 0, '2026-07-20 15:24:35', '2026-07-21 03:45:15'),
(43, 200, 'Yemen\'s Iranian-backed Houthis say they will block Saudi shipping at Red Sea gateway', 'Yemen\'s Iranian-backed Houthi rebels have announced a maritime embargo against Saudi Arabia. Monday\'s decision comes in retaliation for a blockade on Yemen and a recent attack on Sanaa International Airport. The embargo affects the Bab al-Mandeb strait, a crucial waterway for global trade and gateway to the Red Sea as Saudi Arabia seeks an alternative to the Iran-gripped Strait of Hormuz. The blockade raises fears of renewed conflict in the region. Saudi Arabia has not responded. The situation threatens to disrupt global shipping routes and increase costs. The Houthis demonstrated their ability to disrupt shipping there during the war in Gaza.', 'The Atlanta Journal-Constitution', 'https://www.ajc.com/news/2026/07/yemens-iranian-backed-houthis-say-they-will-block-saudi-shipping-at-red-sea-gateway/', 'trade', 'negative', 1, 6, '2026-07-20 08:42:25', '2026-07-21 03:45:15'),
