(46, 175, '\"Want all countries to respect international maritime law\": Panama FM Vasquez voices concern over Hormuz, backs freedom of navigation', 'Panama\'s Foreign Minister Javier Eduardo Martinez-Acha Vasquez on Monday voiced concern over the impact of the ongoing West Asia crisis on global energy markets and maritime trade, warning that disruptions in the Strait of Hormuz could affect oil prices and global supply chains while calling for respect for international maritime law and freedom of navigation.', 'The Tribune', 'https://www.tribuneindia.com/news/world/want-all-countries-to-respect-international-maritime-law-panama-fm-vasquez-voices-concern-over-hormuz-backs-freedom-of-navigation/', 'trade', 'negative', 0, 1, '2026-07-20 05:08:19', '2026-07-21 03:45:15'),
