(55, NULL, 'enginestoalgorithms: Former Marine Engineer Turned Supply Chain Executive Releases From Engines to Algorithms, Charting a New Framework for Operational Constraints', 'LOS ANGELES, CA / ACCESS Newswire / July 22, 2026 / Niraj Jha, Senior Director of Logistics at Niagara Bottling LLC, the largest privately held beverage company in the United States, has released From', 'FinanzNachrichten', 'https://www.finanznachrichten.de/nachrichten-2026-07/69098518-enginestoalgorithms-former-marine-engineer-turned-supply-chain-executive-releases-from-engines-to-algorithms-charting-a-new-framework-for-operatio-200.htm', 'logistics', 'neutral', 0, 0, '2026-07-22 15:50:00', '2026-07-26 01:47:41'),
(56, 109, 'Fertiliser vessels stuck at ports, raise supply fears for peak kharif sowing', 'Fertiliser vessels are stranded at Indian ports, hindering crop nutrient dispatch. This congestion raises concerns over timely supplies during the peak kharif sowing season. Port congestion and supply chain disruptions are slowing cargo movement significantly. Rainfall revival has accelerated kharif sowing, increasing the need for timely fertiliser. Inland logistics bottlenecks must not worsen this challenging situation for farmers.', 'The Economic Times', 'https://economictimes.indiatimes.com/news/economy/agriculture/fertiliser-vessels-stuck-at-ports-raise-supply-fears-for-peak-kharif-sowing/articleshow/132546121.cms', 'logistics', 'negative', 0, 2, '2026-07-21 12:25:00', '2026-07-26 01:47:41'),
