(61, 109, 'Indian Seafarer Killed As Commercial Ship Attacked In Black Sea; MEA Condemns Strike', 'The Ministry of External Affairs emphasized that such attacks on merchant shipping threaten maritime safety and international trade. It urged all parties to ensure protection for civilian navigation. Concerns heightened following a similar attack on the MV Golden Leo.', 'Republic World', 'https://www.republicworld.com/india/indian-seafarer-killed-as-commercial-ship-attacked-in-black-sea-mea-condemns-strike-2026-07-25-133388', 'trade', 'negative', 0, 1, '2026-07-24 18:58:39', '2026-07-26 01:47:46'),
(62, 49, 'Canada celebrates new bridge to US during tariff troubles with Trump', 'Canadian officials are celebrating a new U.S.-Canada bridge over the Detroit River. The international span is expected to improve trade on both sides of the border and give travelers another route to both countries. A ribbon-cutting with speeches took place Friday before the Gordie Howe International Bridge opens to vehicle traffic Monday. U.S. and Michigan officials were not invited after President Donald Trump announced 50% tariffs on Canadian goods this week. A soloist sang the national anthem, “O Canada,” but the U.S. anthem was not performed.', 'The Atlanta Journal-Constitution', 'https://www.ajc.com/news/2026/07/canada-celebrates-new-bridge-to-us-during-tariff-troubles-with-trump/', 'trade', 'neutral', 1, 1, '2026-07-24 13:51:30', '2026-07-26 01:47:46'),
(63, NULL, 'Small Businesses Challenge Trump\'s New Tariffs in Court', 'Two U.S. small businesses have sued the Trump administration, challenging new tariffs on goods from 60 trading partners, claiming they exceed the president\'s authority. The lawsuit, filed in New York\'s U.S. Court of International Trade, argues that these tariffs are not legally justified and could harm American importers.', 'Devdiscourse', 'https://www.devdiscourse.com/article/law-order/3955409-small-businesses-challenge-trumps-new-tariffs-in-court', 'trade', 'neutral', 0, 0, '2026-07-24 13:50:17', '2026-07-26 01:47:46'),
(64, NULL, 'Trade 24/7 Expands Customer Support with Multilingual Assistance for Global Traders', 'Dubai, UAE, July 24th, 2026Trade 24/7 has expanded its customer support services by introducing multilingual assistance to better serve its growing international client base. Traders can now receive support in English,', 'Benzinga', 'https://www.benzinga.com/content/60682675/trade-24-7-expands-customer-support-multilingual-assistance-global-traders', 'trade', 'neutral', 0, 0, '2026-07-24 13:40:21', '2026-07-26 01:47:46'),
(65, NULL, '\"Nations are seeking legal predictability\": EAM Jaishankar calls for harmonised trade rules at UNCITRAL conference', 'Addressing the evolving dynamics of international trade, the minister stressed that legal development cannot remain insulated from changing global realities. He noted that standardised legal frameworks are critical to keeping cross-border flows moving reliably amidst systemic uncertainty.', 'The Tribune', 'https://www.tribuneindia.com/news/world/nations-are-seeking-legal-predictability-eam-jaishankar-calls-for-harmonised-trade-rules-at-uncitral-conference/', 'trade', 'negative', 0, 1, '2026-07-24 12:18:01', '2026-07-26 01:47:46'),
(66, NULL, '\"Nations are seeking legal predictability\": EAM Jaishankar calls for harmonised trade rules at UNCITRAL conference', 'Addressing the evolving dynamics of international trade, the minister stressed that legal development cannot remain insulated from changing global realities. He noted that standardised legal frameworks are critical to keeping cross-border flows moving reliably amidst systemic uncertainty.', 'ANI (Asian News International)', 'https://www.aninews.in/news/world/asia/nations-are-seeking-legal-predictability-eam-jaishankar-calls-for-harmonised-trade-rules-at-uncitral-conference20260725004528/', 'trade', 'negative', 0, 1, '2026-07-24 12:15:28', '2026-07-26 01:47:46'),
(67, 49, 'Bridging Borders: Canada\'s Strategic Move Amid Tariff Tensions', 'Canada celebrated the opening of the Gordie Howe International Bridge linking Windsor and Detroit amid strained U.S.-Canada relations due to tariff disputes with U.S. President Donald Trump. Both countries remain divided on toll-sharing agreements, highlighting ongoing trade negotiations and their longstanding partnership.', 'Devdiscourse', 'https://www.devdiscourse.com/article/law-order/3955352-bridging-borders-canadas-strategic-move-amid-tariff-tensions', 'trade', 'negative', 1, 2, '2026-07-24 10:48:41', '2026-07-26 01:47:46'),
(68, NULL, 'Euro Zone Business Rebounds Amid Global Challenges', 'Euro zone business activity showed growth in July after four stagnant months, driven by new orders. The S&P Global Flash Euro zone Composite PMI Output Index climbed to 51.9, the highest in five months. Despite geopolitical tensions and inflation, the region\'s economy is showing signs of momentum.', 'Devdiscourse', 'https://www.devdiscourse.com/article/business/3955069-euro-zone-business-rebounds-amid-global-challenges', 'economy', 'neutral', 1, 1, '2026-07-24 01:01:29', '2026-07-26 01:47:54'),
(69, 108, 'Landsbankinn hf.: Financial results of Landsbankinn in the first half of 2026', 'Landsbankinn’s net after-tax profit for the first half of 2026 was ISK 22.1 billion, compared with ISK 18.3 billion for the same period of 2025. Landsbankinn’s profit for the second quarter was ISK 11 billion.Return on equity (ROE) was 13.4% compared with 11.5% for the same period the previous year.Net impairment changes increase from the previous year, in part reflecting reassessment and changes in the weighting of scenarios in light of persistent inflation and continued uncertainty in the global economy.  Loans in arrears remain low.Net interest income increases between years and amounted to ISK 39.8 billion. The direct impact of inflation remains unusually high. The net interest margin is currently 3.4% but is expected to be 2.9-3.1% for the full year.Net fee and commission income was ISK 6.2 billion, more or less unchanged between years.The premium over the Central Bank’s key policy rates is lowest for 12-month fixed-rate mortgage loans, at 1.25 percentage points.Performance from insurance contracts was ISK 1.6 billion, up by over 50% between years.  The combined ratio of TM was 89.9% for the first half of 2026.The Group’s cost-income ratio was 31.5%, compared with 35.8% for the same period of 2025. The ratio decreases with increased income while costs remain stable.Imputed income and bank tax was ISK 10.1 billion, compared with ISK 8.5 billion for the same period last year. The total increase is 18.3%.The total capital ratio was 24.7% at the end of the period. The Financial Supervisory Authority (FSA) of the Central Bank of Iceland sets the total capital requirement at 20.0%.The Bank’s Annual General Meeting on 18 March 2026 approved payment of a dividend to shareholders in the amount of ISK 18.9 billion as a regular dividend and a special dividend in the amount of ISK 16.1 billion. Dividend payments for the financial year 2025 thus total ISK 34.9 billion. As a result, total dividends paid by Landsbankinn since 2013 amount to ISK 245.5 billion. Lilja Björk Einarsdóttir, CEO of Landsbankinn:', 'The Manila Times', 'https://www.manilatimes.net/2026/07/24/tmt-newswire/globenewswire/landsbankinn-hf-financial-results-of-landsbankinn-in-the-first-half-of-2026/2390572', 'economy', 'positive', 5, 3, '2026-07-23 09:26:50', '2026-07-26 01:47:54'),
(70, 109, 'Indian economy navigated well external uncertainties: RBI Bulletin', 'Indian economy shows resilience amid global uncertainties, with strong industrial performance and manageable food inflation, says RBI Bulletin.', 'The Hindu', 'https://www.thehindu.com/business/Economy/indian-economy-navigated-well-external-uncertainties-rbi-bulletin/article71253837.ece', 'economy', 'negative', 0, 1, '2026-07-22 08:36:16', '2026-07-26 01:47:54'),
(71, NULL, 'Oil Surges Past $95 Amid Middle East Tensions and Market Fluctuations', 'Oil prices exceeded $95 a barrel as Middle East tensions escalate, impacting U.S. markets. Concerns about supply disruptions arose after threats to oil tankers in the Red Sea. The global economy faces inflation risks, with investor focus on Big Tech earnings and central bank monetary decisions.', 'Devdiscourse', 'https://www.devdiscourse.com/article/business/3954112-oil-surges-past-95-amid-middle-east-tensions-and-market-fluctuations', 'economy', 'negative', 0, 1, '2026-07-22 07:02:12', '2026-07-26 01:47:54'),
(72, NULL, 'Why Persistent Inflation Isn’t Enough to Prevent a Plunge in Gold Prices', 'As persistent inflation continues to drag on the global economy this summer, gold isn’t soaring to new heights. Instead, it is fading away.', 'Barchart', 'https://www.barchart.com/story/news/3384865/why-persistent-inflation-isnt-enough-to-prevent-a-plunge-in-gold-prices', 'economy', 'negative', 0, 2, '2026-07-21 07:33:57', '2026-07-26 01:47:54'),
(73, 2, 'Aluminium Market Faces Turbulence Amid Iran Conflict', 'The aluminium market is grappling with supply disruptions due to escalating conflict in Iran, yet prices have stabilized after an initial spike. This stability is sustained by increased exports from China and emerging suppliers like Indonesia, despite ongoing challenges in Gulf production and geopolitical tensions influencing trade dynamics.', 'Devdiscourse', 'https://www.devdiscourse.com/article/business/3955168-aluminium-market-faces-turbulence-amid-iran-conflict', 'geopolitics', 'negative', 0, 2, '2026-07-24 04:35:51', '2026-07-26 01:47:57'),
(74, NULL, 'Global Market: Stagflation fears return as Gulf conflict, higher energy prices cloud global outlook', 'Renewed conflict in the Gulf has revived stagflation fears as oil prices near $100 a barrel, inflation risks resurface and markets price in further interest rate hikes amid escalating geopolitical and trade tensions.', 'The Economic Times', 'https://economictimes.indiatimes.com/markets/us-stocks/wall-street-guide/global-market-stagflation-fears-return-as-gulf-conflict-higher-energy-prices-cloud-global-outlook/articleshow/132600855.cms', 'geopolitics', 'negative', 0, 3, '2026-07-24 01:59:00', '2026-07-26 01:47:57'),
(75, NULL, 'Gold, Silver Outlook: Investors cautious on gold, silver in no trade zone - Key levels to watch', 'The outlook for gold and silver remains cautious as geopolitical tensions and rising inflation from oil prices weigh on prices. Recent recoveries have not dispelled concerns over interest rate hikes. Future movements will hinge on the U.S.-Iran conflict and signals from US Fed upcoming meeting.', 'Livemint', 'https://www.livemint.com/market/commodities/gold-silver-outlook-investors-cautious-on-gold-price-silver-price-in-no-trade-zone-key-levels-to-watch-11784702238161.html', 'geopolitics', 'negative', 0, 2, '2026-07-22 00:37:46', '2026-07-26 01:47:57'),
(76, 200, 'Global Tensions Surge Oil Prices Amidst Middle Eastern Conflict', 'Oil prices surged by 2% due to escalating tensions in the Middle East, including U.S.-Iran conflicts and Houthi threats against Saudi Arabia. The geopolitical instability has significantly affected global oil supplies and trade, with Brent and U.S. crude reaching multi-week highs.', 'Devdiscourse', 'https://www.devdiscourse.com/article/science-environment/3953634-global-tensions-surge-oil-prices-amidst-middle-eastern-conflict', 'geopolitics', 'negative', 0, 2, '2026-07-21 08:29:16', '2026-07-26 01:47:57');

